// 正确：用信号量限制「同时进行的请求数」，而不是限制线程数
private static final Semaphore LIMIT = new Semaphore(64);

void handle(Request req) {
    try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
        executor.submit(() -> {
            LIMIT.acquire();          // 限制下游并发，保护数据库
            try { return callDownstream(req); }
            finally { LIMIT.release(); }
        });
    }
}

