// 每个 Java 程序启动时 JVM 会造一个主线程，把 main() 放在栈底
// 线程有自己的：调用栈、程序计数器、局部变量
// 线程共享：堆内存、对象（→ 下一章并发问题的根源）
// JVM 还会自己启动别的线程（如 GC 垃圾回收线程）

// Runnable = 线程的工作说明书，只有一个方法 run()
public class MyRunnable implements Runnable {
  public void run() { go(); }        // run() 会成为新栈的栈底（第一个执行的方法）
  public void go() { doMore(); }
  public void doMore() {
    System.out.println(Thread.currentThread().getName() + ": top o' the stack");
    Thread.dumpStack();              // 打印当前调用栈，仅用于调试
  }
}

// 错误示范：直接调 run() 不会开新线程！
MyRunnable r = new MyRunnable();
r.run();   // 只是普通方法调用，跑在 main 的栈上：main→run→go→doMore
