// 线程状态（书里的教学模型 / 括号里是 Java 官方 Thread.State）
// NEW（新建）        —— new Thread(r) 之后，start() 之前，只是个普通对象
//   ↓ start()
// RUNNABLE（可运行） —— 已准备好，有了一条新栈，等调度器选中（在排队，不是在跑）
//   ↓ 被调度器选中
// RUNNING（运行中）  —— 正在 CPU 上执行，栈顶方法在跑（单核上同时只有一条）
//   ├→ 被切回 RUNNABLE（时间片到 / 被抢占）
//   └→ 临时不可运行（BLOCKED/WAITING/TIMED_WAITING）
//        原因：sleep、等流里数据、等别的线程结束、等对象锁
//        原因消失 → 回 RUNNABLE
// run() 执行完 → 线程死亡（官方 TERMINATED）
//
// 关键：进入 RUNNABLE 时新栈就已建立，run() 在栈底等着执行

// 同一段代码，同一台机器，多次运行输出顺序不同：
ExecutorService executor = Executors.newSingleThreadExecutor();
executor.execute(() -> System.out.println("top o' the stack"));
System.out.println("back in main");
executor.shutdown();
// 可能输出 A：top o' the stack / back in main
// 可能输出 B：back in main / top o' the stack
// 原因：调度器可能在 new thread 那一行代码执行到一半时切走它

// 铁律：
// 1. 没有任何 API 能控制调度器
// 2. 调度没有任何公平/顺序保证，线程可能「饿死」
// 3. 不要把程序正确性建立在特定调度行为上（跨平台、不可复现）
// 4. 正确的并发代码 = 对任何调度交错都正确

// sleep：让「当前线程」至少睡指定时长，醒来回 RUNNABLE，何时真跑由调度器定
try { Thread.sleep(2000); }            // 2000 毫秒
catch (InterruptedException e) { e.printStackTrace(); }
// InterruptedException 是受检异常：睡眠被别的线程 interrupt() 打断时抛出

// 更可读的写法（TimeUnit 枚举帮你换算单位，本质还是 Thread.sleep）
try { TimeUnit.MINUTES.sleep(2); }     // 比 Thread.sleep(120000) 清楚得多
catch (InterruptedException e) { e.printStackTrace(); }

// 用 sleep「制造」可预测：让新线程先睡，main 先打印
private static void sleepThenPrint() {
  try { TimeUnit.SECONDS.sleep(2); } catch (InterruptedException e) { e.printStackTrace(); }
  System.out.println("top o' the stack");
}
