// 输出交错方式不可预测 —— 又一次印证「调度不可依赖」
// 池化思想：创建代价高的资源（线程、数据库连接）养个池子反复用，是通用模式

// 关闭线程池三件套
ExecutorService pool = Executors.newFixedThreadPool(2);
pool.execute(new LongJob("Long Job"));
pool.execute(new ShortJob("Short Job"));

// ① 温和关闭：现有+排队任务都跑完，拒绝新任务（再提交会抛 RejectedExecutionException）
pool.shutdown();
try {
  // ② 等待关闭完成，最多 5 秒；true=全完成，false=超时（注意：必须先 shutdown 再 await！）
  boolean finished = pool.awaitTermination(5, TimeUnit.SECONDS);
  System.out.println("Finished? " + finished);
} catch (InterruptedException e) { e.printStackTrace(); }
// ③ 兜底强关：尽量中断正在跑的、丢弃排队的；若已关则无副作用
pool.shutdownNow();
// 经典范式：shutdown → awaitTermination(超时) → shutdownNow 兜底
// shutdownNow 只是「请求停止」，任务不响应 interrupt 未必真停（Java 无安全强杀线程之法）

